<script setup lang="ts">
import {vRememberDisclosure} from './rememberDisclosure'
import {computed,ref} from 'vue'
import type {EventForecast,ForecastAudit,ForecastResearch,ForecastMetrics,ForecastScorecard} from './v6ForecastTypes'
const props=defineProps<{forecast?:EventForecast|null,audit?:ForecastAudit|null,research?:ForecastResearch|null,scorecard?:ForecastScorecard|null}>()
const target=ref('drop3'),family=ref('macro')
const candidate=computed(()=>props.research?.targets.find(t=>t.key===target.value)?.candidates[family.value])
const pct=(v:number|null|undefined,d=1)=>v==null?'—':`${v.toFixed(d)}%`
const fmt=(v:number|null|undefined)=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:2})
const skill=(m:ForecastMetrics|null|undefined)=>m?.brier_skill_pct==null?'樣本不足':`${m.brier_skill_pct>0?'+':''}${m.brier_skill_pct.toFixed(2)}%`
const auditText=(row:ForecastAudit['targets'][number])=>row.status==='pending'?`待滿期 · 尚差 ${row.remaining_sessions} 個交易日`:row.status==='complete'?(row.occurred?'已發生':'未發生'):row.status==='not_applicable'?'不適用':row.reason||'資料待核對'
</script>
<template>
 <details v-remember-disclosure="'v6.forecast'" open class="event-forecast" aria-label="V6 新版事件預報">
  <summary class="section-summary"><div><span class="eyebrow">V6 · EVENT FORECAST</span><h2>跌勢預報與事後核對</h2><p>分開追蹤收跌、期間回落、跌勢擴大與反彈。新預報只在對話要求更新 V6 時保存。</p></div><span class="badge">研究驗證中</span></summary>
  <div v-if="!forecast?.targets?.length" class="notice">{{forecast?.reason||'這份舊紀錄尚無新版事件預報；下次在對話中更新 V6 時才建立，不回填歷史預測。'}}<small>下方是已完成的歷史檢驗，不代表今天的預報。</small></div>
  <template v-else>
   <div class="anchor">{{forecast.as_of}} 收盤基準 <b>{{fmt(forecast.anchor_close)}}</b> · {{forecast.family_label}}<small>{{forecast.note}}</small></div>
   <div class="targets"><article v-for="row in forecast.targets" :key="row.key"><h3>{{row.label}}</h3><b>{{pct(row.probability_pct)}}</b><div class="meter" v-if="row.probability_pct!=null"><i :style="{width:Math.min(100,Math.max(0,row.probability_pct))+'%'}"/></div><p>{{row.reason||'已校準的研究估計，需持續核對。'}}</p><small>校準期基準 {{pct(row.baseline_pct)}}</small></article></div>
   <div v-if="forecast.downside_range" class="range"><h3>未來 5 日期間最低報酬範圍</h3><div><article v-for="(value,i) in forecast.downside_range.quantiles_pct" :key="i"><small>{{['較差十分位','中位數','較輕十分位'][i]}}</small><b>{{pct(value,2)}}</b></article></div><p>{{forecast.downside_range.method}} 「較差十分位」以外仍可能發生更大跌幅。</p></div>
   <div v-if="audit?.targets.length" class="audit"><h3>本次預報核對 <small>行情至 {{audit.checked_through}}</small></h3><div class="table-wrap"><table><thead><tr><th>目標</th><th>保存機率</th><th>到期日</th><th>結果</th><th>期間最低報酬</th></tr></thead><tbody><tr v-for="row in audit.targets" :key="row.key"><td>{{row.label}}</td><td>{{pct(row.probability_pct)}}</td><td>{{row.target_date||'等待交易日'}}</td><td>{{auditText(row)}}</td><td>{{pct(row.minimum_return_pct,2)}}</td></tr></tbody></table></div><p>核對只讀取保存預報與後續行情，不重估當時機率。反彈確認不等於風險完全解除。</p></div>
   <details v-remember-disclosure="'v6.forecast.signals'" v-if="forecast.observations?.length" class="signals" open><summary>提早惡化觀察</summary><div><article v-for="row in forecast.observations" :key="row.label"><h3>{{row.label}}</h3><b>{{fmt(row.value)}} {{row.unit}}</b><small>{{row.as_of}}<span v-if="row.n"> · {{fmt(row.n)}} 檔</span></small><p>{{row.note}}</p></article></div></details>
  </template>
  <div v-if="scorecard" class="audit"><h3>正式保存後的預報成績</h3><p>新版已保存 {{scorecard.saved}} 份。{{scorecard.note}}</p><div v-if="scorecard.rows.length" class="table-wrap"><table><thead><tr><th>目標／時段</th><th>已到期／待到期</th><th>平均預報機率</th><th>實際發生比例</th><th>機率誤差</th></tr></thead><tbody><tr v-for="row in scorecard.rows" :key="row.version+row.family+row.label"><td>{{row.label}}<small>{{row.family==='macro'?'盤前海外模型':'盤後價格模型'}}</small></td><td>{{row.completed}}／{{row.pending}}<small>未發布數字 {{row.withheld}} 次</small></td><td>{{pct(row.mean_probability_pct)}}</td><td>{{pct(row.actual_rate_pct)}}</td><td>{{row.brier?.toFixed(4)||'—'}}</td></tr></tbody></table></div></div>
  <div v-if="research" class="research">
   <h3>歷史驗證：有沒有比一般機率更好？</h3><p>資料至 {{research.data_through}}；逐年測試，自 2021 年起。下表數字是機率誤差相對基準的改善幅度，<b>不是下跌機率或交易勝率</b>。正值較好，負值較差；使用各模型共同可用日期比較。重疊目標的日樣本不代表獨立股災次數。</p>
   <div class="table-wrap"><table><thead><tr><th>預報目標</th><th v-for="(name,key) in research.candidate_names" :key="key">{{name}}</th></tr></thead><tbody><tr v-for="row in research.targets" :key="row.key"><td>{{row.label}}</td><td v-for="(_,key) in research.candidate_names" :key="key"><b :class="{better:(row.matched_dates[key]?.brier_skill_pct||0)>0}">{{skill(row.matched_dates[key])}}</b><small v-if="row.matched_dates[key]">{{fmt(row.matched_dates[key]?.n)}} 個日樣本 · {{fmt(row.matched_dates[key]?.events)}} 次觸及</small></td></tr></tbody></table></div>
   <p class="notice">盤前模型包含已發生的美股收盤反應，不能把這項改善解讀成提早數天預知突發消息。5% 急跌與更大股災事件少，沒有足夠證據就不發布數字。</p>
   <details v-remember-disclosure="'v6.forecast.diagnostics'" class="diagnostics"><summary>查看誤報、提前天數與校準細節</summary><div class="selectors"><label>目標<select v-model="target"><option v-for="row in research.targets" :key="row.key" :value="row.key">{{row.label}}</option></select></label><label>模型<select v-model="family"><option v-for="(name,key) in research.candidate_names" :key="key" :value="key">{{name}}</option></select></label></div>
    <div v-if="candidate?.metrics" class="metric-grid"><article><small>校準前誤差</small><b>{{candidate.raw_metrics?.brier.toFixed(4)||'—'}}</b></article><article><small>校準後誤差（越低越好）</small><b>{{candidate.metrics.brier.toFixed(4)}}</b></article><article><small>改善幅度 95% 區間</small><b>{{candidate.metrics.skill_range_95?.map(v=>pct(v)).join(' ～ ')||'不足'}}</b></article></div>
    <div v-if="candidate?.episodes" class="metric-grid"><article><small>合併後警報</small><b>{{candidate.episodes.alerts}} 次</b><small>成功 {{candidate.episodes.true_alerts}} · 誤報 {{candidate.episodes.false_alerts}}</small></article><article><small>每月平均誤報</small><b>{{fmt(candidate.episodes.false_alerts_per_month)}} 次</b></article><article><small>捕捉事件的提前中位數</small><b>{{fmt(candidate.episodes.median_lead_sessions)}} 個交易日</b><small>漏報 {{candidate.episodes.missed_windows}}／{{candidate.episodes.event_windows}} 個事件</small></article></div>
    <p>{{candidate?.episodes?.note||'此目標尚無足夠樣本。'}} 95% 區間以 20 日區塊重抽樣估計；仍可能低估長期制度變化。</p>
    <div class="table-wrap" v-if="candidate?.bins.some(b=>b.n)"><table><thead><tr><th>預報機率區間</th><th>平均預報</th><th>實際發生比例</th><th>日樣本</th></tr></thead><tbody><tr v-for="bin in candidate.bins.filter(b=>b.n)" :key="bin.low"><td>{{pct(bin.low*100,0)}}～{{pct(bin.high*100,0)}}</td><td>{{pct(bin.predicted_pct)}}</td><td>{{pct(bin.actual_pct)}}</td><td>{{bin.n}}</td></tr></tbody></table></div>
   </details>
   <details v-remember-disclosure="'v6.forecast.method'" class="method"><summary>研究規則與來源</summary><p v-for="(value,key) in research.protocol" :key="key">{{value}}</p><p>{{research.evidence}}</p><p>集保持股、融資與廣度歷史不足的項目先列觀察；新聞不直接加分。跌幅範圍採波動標準化歷史分布，本版沒有宣稱已實作 CAViaR。</p><p v-if="research.downside_range">最低報酬十分位歷史覆蓋檢驗：下十分位 {{pct(research.downside_range.coverage_10_pct)}}（目標10%），上十分位 {{pct(research.downside_range.coverage_90_pct)}}（目標90%）。</p><ul><li v-for="s in research.sources" :key="s.url"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title}}</a></li></ul></details>
  </div>
 </details>
</template>
<style scoped>
.event-forecast{border:1px solid #dfe6dd;border-radius:16px;background:#fff;margin:18px 0;overflow:hidden;color:#33483c}.section-summary{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:24px;border-bottom:1px solid #e8ede7}.eyebrow{font-size:10px;letter-spacing:.15em;color:#7d8b7d}h2{font-size:23px;margin:7px 0}h3{font-size:15px;margin:0 0 10px}p,small{color:#7e8b7e;line-height:1.7;font-size:12px}p{margin:7px 0}small{display:block}.badge{white-space:nowrap;background:#f6eddb;color:#937545;border-radius:99px;padding:7px 12px;font-size:12px}.notice{padding:14px 18px;margin:18px 24px;background:#faf4e8;border:1px solid #eae0cc;border-radius:10px;color:#826b42}.anchor,.research,.audit,.range,.signals{padding:22px 24px;border-top:1px solid #edf0e9}.targets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:0 24px 22px}.targets article{border:1px solid #e5ebe3;border-radius:12px;padding:17px}.targets article>b{font:700 28px Georgia,serif;color:#a46555}.meter{height:6px;background:#eee8df;border-radius:4px;margin:12px 0}.meter i{display:block;height:100%;background:#b67c64;border-radius:4px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:right;padding:14px 12px;border-bottom:1px solid #e9eee7;white-space:nowrap}th{background:#f5f7f2;color:#7a8877}td:first-child,th:first-child{text-align:left}td small{font-size:10px}.better{color:#33785c}.metric-grid,.range>div,.signals>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}.metric-grid article,.range article,.signals article{background:#f5f8f3;border-radius:10px;padding:16px}.metric-grid b,.range b,.signals b{display:block;font-size:19px;margin:8px 0}.diagnostics,.method{margin-top:20px;border-top:1px solid #e9eee7;padding-top:18px}summary{cursor:pointer;font-weight:700;font-size:14px}.selectors{display:flex;flex-wrap:wrap;gap:14px;margin:18px 0}.selectors label{font-size:12px;color:#7e8b7e}.selectors select{display:block;max-width:100%;padding:8px;border:1px solid #d9e1d5;border-radius:8px;background:#fff;color:#43573f}.research>.notice{margin:18px 0}a{color:#3c7660}li{font-size:12px;line-height:1.8}.audit h3 small{display:inline;font-weight:400;margin-left:8px}@media(max-width:850px){.targets,.metric-grid,.range>div,.signals>div{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.section-summary{align-items:start;flex-direction:column}.targets,.metric-grid,.range>div,.signals>div{grid-template-columns:1fr}.targets{padding:0 14px 16px}.anchor,.research,.audit,.range,.signals,.section-summary{padding:18px 14px}.notice{margin:14px}.selectors{display:block}.selectors label{display:block;margin:10px 0}.selectors select{width:100%}}
</style>
